import{_ as p,a0 as o,w as d,s as r,I as a,x as e,a1 as l,A as i,ao as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"如何使用 firewall-cmd 管理網絡服務 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 firewall-cmd 管理網絡服務 | LCTT (202006) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 firewall-cmd 管理網絡服務 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 firewall-cmd 管理網絡服務 | LCTT (202006) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202006/20200511 How to manage network services with firewall-cmd","title":"如何使用 firewall-cmd 管理網絡服務","tag":"202006","desc":""},"relativePath":"202006/20200511 How to manage network services with firewall-cmd.md","filePath":"[post].md"}'),c={name:"202006/20200511 How to manage network services with firewall-cmd.md"};function m(h,s,g,f,u,k){const n=o("Link");return d(),r("div",null,[s[22]||(s[22]=a("h1",{id:"如何使用-firewall-cmd-管理網絡服務",tabindex:"-1"},[e("如何使用 firewall-cmd 管理網絡服務 "),a("a",{class:"header-anchor",href:"#如何使用-firewall-cmd-管理網絡服務","aria-label":"Permalink to “如何使用 firewall-cmd 管理網絡服務”"},"​")],-1)),s[23]||(s[23]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202006/03/090806hcmc9cxcbbcuccbe.jpg",alt:""})],-1)),a("p",null,[s[1]||(s[1]=e("在上一篇文章中，我們探討了如何在 Fedora 中",-1)),l(n,{href:"https://linux.cn/article-12103-1.html"},{default:i(()=>[...s[0]||(s[0]=[e("用命令列控制防火牆",-1)])]),_:1}),s[2]||(s[2]=e("。",-1))]),s[24]||(s[24]=t(`<p>現在你將看到如何“添加”、“刪除”和“列出”服務、協議和端口，以便“阻止”或“允許”它們。</p><h3 id="簡短回顧" tabindex="-1">簡短回顧 <a class="header-anchor" href="#簡短回顧" aria-label="Permalink to “簡短回顧”">​</a></h3><p>首先，最好檢查一下防火牆的<em>狀態</em>，看它是否正在運行。如我們先前所學，你可以使用狀態選項（<code>firewall-cmd ‐‐state</code>）來得到。</p><p>下一步是獲取網絡接口適用的<ruby>域<rt>zone</rt></ruby>。例如，我使用的桌面有兩個網絡接口：一個<em>物理</em>接口（<code>enp0s3</code>），代表我實際的<em>網卡</em>，和<em>虛擬</em>接口（<code>virbr0</code>），它由 KVM 等虛擬化軟件使用。要查看哪些域處於活動狀態，請運行 <code>firewall-cmd ‐‐get-active-zones</code>。</p><p>現在，你知道了你感興趣的域，可以使用 <code>firewall-cmd ‐‐info-zone=FedoraWorkstation</code> 這樣的命令列出該域的規則。</p><h3 id="讀取區域信息" tabindex="-1">讀取區域信息 <a class="header-anchor" href="#讀取區域信息" aria-label="Permalink to “讀取區域信息”">​</a></h3><p>要顯示<em>特定域</em>的信息，請運行 <code>firewall-cmd ‐‐zone=ZoneName ‐‐list-all</code>，或使用以下命令顯示默認域的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[dan@localhost ~]$ firewall-cmd --list-all</span></span>
<span class="line"><span>FedoraWorkstation (active)</span></span>
<span class="line"><span>target: default</span></span>
<span class="line"><span>icmp-block-inversion: no</span></span>
<span class="line"><span>interfaces: enp0s3</span></span>
<span class="line"><span>sources:</span></span>
<span class="line"><span>services: dhcpv6-client mdns samba-client ssh</span></span>
<span class="line"><span>ports: 1025-65535/udp 1025-65535/tcp</span></span>
<span class="line"><span>protocols:</span></span>
<span class="line"><span>masquerade: no</span></span>
<span class="line"><span>forward-ports:</span></span>
<span class="line"><span>source-ports:</span></span>
<span class="line"><span>icmp-blocks:</span></span>
<span class="line"><span>rich rules:</span></span></code></pre></div><p>現在，讓我們查看輸出。第一行表明以下信息關聯的域以及該域當前是否在使用中。</p><p><code>target: default</code>：告訴我們這是默認域。可以通過 <code>‐‐set-default-zone=ZoneName</code> 和 <code>‐‐get-default-zone</code> 設置或獲取。</p>`,10)),a("p",null,[s[4]||(s[4]=a("code",null,"icmp-block-inversion",-1)),s[5]||(s[5]=e(" 表明是否阻止 ",-1)),l(n,{href:"https://en.wikipedia.org/wiki/Internet_Control_Message_Protocol"},{default:i(()=>[...s[3]||(s[3]=[e("ICMP",-1)])]),_:1}),s[6]||(s[6]=e(" 請求。例如，如果機器響應來自網絡上其他機器的 ping 請求。",-1))]),s[25]||(s[25]=t(`<p><code>interfaces</code> 字段顯示接受此域的所有接口。</p><h3 id="處理服務、端口和協議" tabindex="-1">處理服務、端口和協議 <a class="header-anchor" href="#處理服務、端口和協議" aria-label="Permalink to “處理服務、端口和協議”">​</a></h3><p>現在，重點關注 <code>services</code>、<code>ports</code> 和 <code>protocols</code> 所在行。默認情況下，防火牆將阻止所有端口、服務和協議，而只允許列出的。</p><p>在這裏，你可以看到允許的服務是非常基本的客户端服務。例如，訪問網絡上的共享文件夾（<code>samba-client</code>）、與 DNS 服務器通信或通過 SSH（<code>ssh</code> 服務）連接到計算機。你可以將 <code>service</code> 視為與端口組合的協議，例如 <code>ssh</code> 服務使用 SSH 協議，並且按照慣例使用 22 端口。通過允許 <code>ssh</code> 服務，你實際上所做的就是允許傳入的連接在默認 22 端口上使用 SSH 協議。</p><p>請注意，根據經驗，名稱中帶有 <code>client</code> 字樣的服務是指傳出連接，也就是你使用你的 IP 作為源對外部的<em>連接</em>，與之相反的是 <code>ssh</code> 服務，比如，它將接受傳入連接（監聽來自外部的連接）。</p><p>你可以在文件 <code>/etc/services</code> 中查找服務。例如，如果你想知道這些服務使用什麼端口和協議：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[dan@localhost ~]$ cat /etc/services | grep ssh</span></span>
<span class="line"><span>ssh 22/tcp # The Secure Shell (SSH) Protocol</span></span>
<span class="line"><span>ssh 22/udp # The Secure Shell (SSH) Protocol</span></span></code></pre></div><p>你可以看到 SSH 同時使用 TCP 和 UDP 的 22 端口。此外，如果你希望查看所有可用的服務，只需使用 <code>firewall-cmd --get-services</code>。</p><h4 id="打開端口" tabindex="-1">打開端口 <a class="header-anchor" href="#打開端口" aria-label="Permalink to “打開端口”">​</a></h4><p>如果要阻止端口、服務或協議，請確保在此處未列出它們。展開來説，如果要允許服務，那麼需要將它添加到列表中。</p><p>假設你要打開 <code>5000</code> 端口用於 TCP 連接。為此，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo firewall-cmd --zone=FedorwaWorkstation --permanent --add-port=5000/tcp</span></span></code></pre></div><p>請注意，你需要指定規則適用的域。添加規則時，還需要如上指定它是 <code>tcp</code> 還是 <code>udp</code> 端口。<code>--permanent</code> 參數將規則設置為即使系統重啓後也可以保留。</p><p>再次查看你所在區域的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[dan@localhost ~]$ firewall-cmd --list-all</span></span>
<span class="line"><span>FedoraWorkstation (active)</span></span>
<span class="line"><span>target: default</span></span>
<span class="line"><span>icmp-block-inversion: no</span></span>
<span class="line"><span>interfaces: enp0s3</span></span>
<span class="line"><span>sources:</span></span>
<span class="line"><span>services: dhcpv6-client mdns samba-client ssh</span></span>
<span class="line"><span>ports: 1025-65535/udp 1025-65535/tcp 5000/tcp</span></span>
<span class="line"><span>protocols:</span></span>
<span class="line"><span>masquerade: no</span></span>
<span class="line"><span>forward-ports:</span></span>
<span class="line"><span>source-ports:</span></span>
<span class="line"><span>icmp-blocks:</span></span>
<span class="line"><span>rich rules:</span></span></code></pre></div><p>類似地，如果你想從列表刪除該端口，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo firewall-cmd --zone=FedorwaWorkstation --permanent --remove-port=5000/tcp</span></span></code></pre></div><p>相同的 <code>remove</code> （<code>‐‐remove-protocol</code>、<code>‐‐remove-service</code>） 和 <code>add</code>（<code>‐‐add-protocol</code>、<code>‐‐add-service</code>）選項同樣適用於<em>服務</em>和<em>協議</em>。</p><hr>`,19)),a("p",null,[s[8]||(s[8]=e("via: ",-1)),l(n,{href:"https://fedoramagazine.org/how-to-manage-network-services-with-firewall-cmd/"},{default:i(()=>[...s[7]||(s[7]=[e("https://fedoramagazine.org/how-to-manage-network-services-with-firewall-cmd/",-1)])]),_:1})]),a("p",null,[s[13]||(s[13]=e("作者：",-1)),l(n,{href:"https://fedoramagazine.org/author/dan01/"},{default:i(()=>[...s[9]||(s[9]=[e("dan01",-1)])]),_:1}),s[14]||(s[14]=e(" 選題：",-1)),l(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[10]||(s[10]=[e("lujun9972",-1)])]),_:1}),s[15]||(s[15]=e(" 譯者：",-1)),l(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[11]||(s[11]=[e("geekpi",-1)])]),_:1}),s[16]||(s[16]=e(" 校對：",-1)),l(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[12]||(s[12]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[19]||(s[19]=e("本文由 ",-1)),l(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[17]||(s[17]=[e("LCTT",-1)])]),_:1}),s[20]||(s[20]=e(" 原創編譯，",-1)),l(n,{href:"https://linux.cn/"},{default:i(()=>[...s[18]||(s[18]=[e("Linux中國",-1)])]),_:1}),s[21]||(s[21]=e(" 榮譽推出",-1))])])}const C=p(c,[["render",m]]);export{v as __pageData,C as default};
